package org.example.insurance.policy;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/policies") public class PolicyController { private final PolicyRepository policies; private final RestClient holders; private final RestClient products; PolicyController(PolicyRepository policies,@Value("${clients.policyholder-url}") String h,@Value("${clients.product-url}") String p){this.policies=policies;holders=RestClient.create(h);products=RestClient.create(p);} record IssueRequest(Long policyholderId,Long productId,LocalDate issueDate,LocalDate expiryDate,BigDecimal sumAssured){} @PostMapping public ResponseEntity<InsurancePolicy> issue(@RequestBody IssueRequest r){Map<?,?> eligibility=holders.get().uri("/policyholders/{id}/eligibility",r.policyholderId()).retrieve().body(Map.class);if(!Boolean.TRUE.equals(eligibility.get("eligible"))) return ResponseEntity.unprocessableEntity().build();Map<?,?> product=products.get().uri("/products/{id}",r.productId()).retrieve().body(Map.class);if(!"ACTIVE".equals(product.get("status")))return ResponseEntity.unprocessableEntity().build();InsurancePolicy p=new InsurancePolicy();p.setPolicyholderId(r.policyholderId());p.setProductId(r.productId());p.setIssueDate(r.issueDate());p.setExpiryDate(r.expiryDate());p.setSumAssured(r.sumAssured());p.setPremiumAmount(new BigDecimal(product.get("premiumAmount").toString()));p.setPolicyNumber("POL-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());return ResponseEntity.status(201).body(policies.save(p));} @GetMapping("/{id}") public InsurancePolicy get(@PathVariable Long id){return policies.findById(id).orElseThrow(()->new NoSuchElementException("Policy not found"));} @PutMapping("/{id}/renew") public InsurancePolicy renew(@PathVariable Long id,@RequestParam LocalDate renewalDate,@RequestParam LocalDate expiryDate){InsurancePolicy p=get(id);p.setRenewalDate(renewalDate);p.setExpiryDate(expiryDate);p.setPolicyStatus("ACTIVE");return policies.save(p);} }
